const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var gaul = ee.FeatureCollection("FAO/GAUL/2015/level1");
  var india = gaul.filter(ee.Filter.eq('ADM0_NAME', 'India'));
  var punjab = india.filter(ee.Filter.eq('ADM1_NAME', 'Punjab'));
  var haryana = india.filter(ee.Filter.eq('ADM1_NAME', 'Haryana'));
  var region = punjab.merge(haryana);
  var geometry = region.geometry();

  // 2. Data Acquisition & Processing
  var years = [];
  for (var y = 2012; y <= 2023; y++) years.push(y);
  years.push(2024);

  var fireCounts = {};
  var noData = false;
  var calcFail = false;

  // Function to get fire count for a given November
  function getFireCount(year) {
    var startDate = ee.Date.fromYMD(year, 11, 1);
    var endDate = startDate.advance(1, 'month'); // Dec 1

    // Try primary collection
    var col1 = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML')
                  .filterDate(startDate, endDate)
                  .filterBounds(geometry);
    var col = col1;
    var numImages = col1.size().getInfo();
    if (numImages === 0) {
      // Fallback to alternative VIIRS collection
      var col2 = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1')
                    .filterDate(startDate, endDate)
                    .filterBounds(geometry);
      numImages = col2.size().getInfo();
      if (numImages === 0) {
        return {count: null, images: 0}; // No data
      }
      col = col2;
    }

    // Create binary fire mask (FireMask >= 4 indicates fire)
    var fireImages = col.map(function(image) {
      var fireMask = image.select('FireMask');
      var fireBinary = fireMask.gte(4).rename('fire');
      return fireBinary;
    });

    // Sum fire detections over the month
    var sumImage = fireImages.sum();

    // Count total fire pixels over region
    var reduction = sumImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });

    var fireCount = reduction.get('fire').getInfo();

    // Validate result
    if (fireCount === null || fireCount === undefined || isNaN(fireCount)) {
      return {count: undefined, images: numImages};
    }
    return {count: fireCount, images: numImages};
  }

  // 3. Process each year
  for (var i = 0; i < years.length; i++) {
    var year = years[i];
    var result = getFireCount(year);

    if (result.count === null) {
      console.log(year + ' Images: 0');
      noData = true;
      break;
    } else if (result.count === undefined) {
      console.log(year + ' Images: ' + result.images + ' (Val: NaN)');
      calcFail = true;
      break;
    } else {
      fireCounts[year] = result.count;
      console.log(year + ' Images: ' + result.images + ' (Fire count: ' + result.count + ')');
    }
  }

  // 4. Validation & Final Answer
  if (noData) {
    console.log('<answer>C1</answer>');
  } else if (calcFail) {
    console.log('<answer>C3</answer>');
  } else {
    // Check if 2024 fire count is lower than all previous years
    var count2024 = fireCounts[2024];
    var allLower = true;
    for (var y = 2012; y <= 2023; y++) {
      if (count2024 >= fireCounts[y]) {
        allLower = false;
        break;
      }
    }
    if (allLower) {
      console.log('<answer>A</answer>');
    } else {
      console.log('<answer>B</answer>');
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
